            "৭. সংস্কারের নিজস্ব সুপারিশ — পেশাদার সমাজকর্মীদের নিয়োগ: ডিগ্রিধারী পেশাদার সমাজকর্মীদের প্রকল্প পরিচালক হিসেবে নিয়োগ দিয়ে বৈজ্ঞানিক পদ্ধতির প্রয়োগ নিশ্চিত করা।"
