          "step1_intro": "কোনো একক পরিবার বা ব্যক্তির বিচ্ছিন্ন অভাবকে ব্যক্তিক দারিদ্র্য বলা হয়। কিন্তু যখন একটি নির্দিষ্ট ভৌগোলিক এলাকা, জনপদ বা সমগ্র জনগোষ্ঠীর সংখ্যাগরিষ্ঠ মানুষ দীর্ঘদিন ধরে মৌলিক মানবিক চাহিদা মেটাতে ব্যর্থ হয়ে অবমাননাকর জীবনযাপন করে, তখন সেই সামগ্রিক অবস্থাকে 'সমষ্টি দারিদ্র্য' (Community Poverty বা Collective Poverty) বলে। বাংলাদেশের উত্তরাঞ্চলের মঙ্গা এলাকা, নদীভাঙন কবলিত দুর্গম চরাঞ্চল এবং উপকূলীয় লবণাক্ত জনপদ সমষ্টি দারিদ্র্যের প্রকৃষ্ট উদাহরণ। এই দারিদ্র্যের পেছনে ঐতিহাসিক, অর্থনৈতিক, প্রাকৃতিক ও রাজনৈতিক বহুবিধ জটিল কারণ ক্রিয়াশীল রয়েছে।",
