            "৫. আয়ের চরম বৈষম্য ও সম্পদের অসম বণ্টন: দেশের জিডিপি প্রবৃদ্ধি সত্ত্বেও শীর্ষ ৫% ধনীর হাতে জাতীয় সম্পদের সিংহভাগ পুঞ্জীভূত হচ্ছে এবং নিম্ন আয়ের মানুষের প্রকৃত ক্রয়ক্ষমতা হ্রাস পাচ্ছে।",
