            "৩. শ্রেণী মেরুকরণ ও সর্বহারা শ্রেণী (Proletariat): মার্কসের মতে, পুঁজিবাদী প্রতিযোগিতায় ছোট ছোট ব্যবসায়ীরা ধ্বংস হয়ে শ্রমিকের কাতারে নেমে আসে। ফলে সমাজ তীব্রভাবে দুটি চরম শিবিরে বিভক্ত হয়—মুষ্টিমেয় ধনিক বুর্জোয়া এবং নিঃস্ব সর্বহারা শ্রমিক।",
